arguments.command:
cd /workspace; sqlite3 -readonly -header data/warehouse.db "
select changed_by like '%.%' as person, count(*) from crm_opportunity_field_history group by 1;
select changed_by, count(*) from crm_opportunity_field_history where changed_by not like '%.%' group by 1;
select changed_by, count(*) from cs_account_health_history where changed_by not like 'csm.%' group by 1;
select count(*), sum(synced_at<changed_at) from crm_opportunity_field_history;
select count(*), sum(synced_at<changed_at) from cs_account_health_history;
select substr(changed_at,1,7) m, count(*), max(julianday(synced_at)-julianday(changed_at)) from crm_opportunity_field_history group by m order by m desc limit 14;
"

